command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="108cedb5c17a1229604dc6f7a43fbc7c2eb775ab"
$branch="work/shell-provider-visuals-20261007"
Set-Location -LiteralPath $repo
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider branch cleanup fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $main){throw "main moved before provider branch cleanup"}
$remoteRef="refs/remotes/origin/"+$branch
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -ne 0){throw "provider work branch is absent or unresolved"}
$branchHead=(& git rev-parse $remoteRef).Trim()
if($branchHead -ne $main){throw "provider work branch does not point at accepted main"}
& git merge-base --is-ancestor $branchHead $observed
if($LASTEXITCODE -ne 0){throw "provider work branch is not merged into main"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "provider work branch deletion failed"}
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "provider branch post-cleanup fetch failed"}
& git show-ref --verify --quiet $remoteRef
if($LASTEXITCODE -eq 0){throw "provider work branch still exists after deletion"}
Write-Host "SHELL_PROVIDER_VISUAL_WORK_BRANCH_CLEANUP=PASS"
